function money(n){return '$'+Math.round(n).toLocaleString()}
function nav(){var items=[['dashboard','Dashboard'],['work','Work'],['records','Records'],['goals','Goals'],['ai','AI Assist'],['owner','Owner Console']];return '<aside class="side"><div class="brand"><div class="mark">V</div><span>VANTAGE</span></div><div class="sectionLabel">Workspace</div><div class="nav">'+items.map(function(i){return '<button class="'+(S.page===i[0]?'on':'')+'" onclick="go(\''+i[0]+'\')">◼ <span>'+i[1]+'</span></button>'}).join('')+'</div><div class="profile"><b>LCpl John Boletz</b><small>MARFORRES · G-8</small></div></aside>'}
function shell(body,title){return nav()+'<main class="main"><div class="top"><div class="muted">MARFORRES / Command Element</div><button class="search" onclick="showSearch()">Search VANTAGE &nbsp; ⌘K</button></div><div class="content">'+body+'</div></main>'+modal()+toast()}
function head(t,p,action){return '<div class="pagehead"><div><h1>'+t+'</h1><p>'+p+'</p></div>'+(action||'')+'</div>'}
function badge(s){var c=s==='Resolved'?'green':s==='Waiting'?'amber':s==='Open'?'blue':'amber';return '<span class="badge '+c+'">'+s+'</span>'}
function dashboard(){var metrics=[['Actions completed',S.actions,'+12 this week'],['Cases resolved',S.resolved,'81% closure rate'],['Items processed','138','ULOs · UMTs · DOCs'],['Value worked','$2.4M','Across tracked actions'],['Awaiting response','7','2 follow-ups due'],['Due this week','11','3 high priority']];var cards=metrics.map(function(m){return '<div class="metric"><label>'+m[0]+'</label><strong>'+m[1]+'</strong><small>'+m[2]+'</small></div>'}).join('');var work=S.rows.slice(0,3).map(function(r){return '<div class="workitem"><div><div class="doc">'+r.doc+'</div><div class="title">'+(r.status==='Waiting'?'Follow up with '+r.poc:'Review financial action')+'</div><div class="meta">'+badge(r.status)+'<span>'+money(r.amount)+'</span><span>'+r.owner+'</span></div></div><div><b>'+r.due+'</b><br><button class="btn small" onclick="openRow('+r.id+')">Open</button></div></div>'}).join('');return shell(head('Command center','Actual work, actions, outcomes, and what needs attention.','<button class="btn primary" onclick="go(\'work\')">Open Work</button>')+'<div class="metricgrid">'+cards+'</div><div class="grid2"><div class="card"><div class="cardhead"><h2>Make the next move</h2><span class="badge blue">Action-first</span></div>'+work+'</div><div class="card"><div class="cardhead"><h2>Work status</h2></div><div class="bars"><div class="barrow"><span>Resolved</span><div class="bar"><span style="width:72%"></span></div><b>72%</b></div><div class="barrow"><span>Researching</span><div class="bar"><span style="width:48%"></span></div><b>48%</b></div><div class="barrow"><span>Waiting</span><div class="bar"><span style="width:31%"></span></div><b>31%</b></div></div><p style="margin-top:22px">No streaks. No incentive to create fake records. VANTAGE measures completed actions and operational outcomes.</p></div></div>','Dashboard')}
function work(){var tabs=[['queue','My Queue'],['cases','Cases'],['files','Files / Workbook'],['corr','Correspondence']];var t='<div class="tabs">'+tabs.map(function(x){return '<button class="'+(S.tab===x[0]?'on':'')+'" onclick="tab(\''+x[0]+'\')">'+x[1]+'</button>'}).join('')+'</div>';var body=S.tab==='queue'?queue():S.tab==='cases'?cases():S.tab==='files'?files():corr();return shell(head('Work','Coordinate cases, claim work, process spreadsheets, and track correspondence.','<button class="btn primary" onclick="newAction()">+ Log Action</button>')+t+body,'Work')}
function queue(){return '<div class="toolbar"><div class="row"><span class="badge">11 assigned</span><span class="badge amber">3 high priority</span></div><button class="btn">Filter</button></div><div class="tablewrap"><table><thead><tr><th>DOC</th><th>Work</th><th>Amount</th><th>POC</th><th>Status</th><th>Owner</th><th>Due</th><th></th></tr></thead><tbody>'+S.rows.map(function(r){return '<tr><td class="doc">'+r.doc+'</td><td>ULO / obligation research</td><td>'+money(r.amount)+'</td><td>'+r.poc+'</td><td>'+badge(r.status)+'</td><td>'+r.owner+'</td><td>'+r.due+'</td><td><button class="btn small" onclick="'+(r.owner==='Unclaimed'?'claim('+r.id+')':'openRow('+r.id+')')+'">'+(r.owner==='Unclaimed'?'Claim':'Open')+'</button></td></tr>'}).join('')+'</tbody></table></div>'}
function cases(){return '<div class="grid2"><div class="card"><div class="cardhead"><h2>Active cases</h2><span class="badge blue">DOC-centered</span></div>'+S.rows.map(function(r){return '<div class="workitem" onclick="openRow('+r.id+')"><div><div class="doc">'+r.doc+'</div><div class="title">ULO research · '+r.poc+'</div><div class="meta">'+badge(r.status)+'<span>'+money(r.amount)+'</span></div></div><b>'+r.due+'</b></div>'}).join('')+'</div><div class="card"><h2>Case model</h2><p>Each case connects DOC data, tasks, financial values, actions, files, correspondence, and an attributable timeline.</p><div class="timeline"><div><b>09:08 · Claimed</b><small>LCpl Boletz</small></div><div><b>09:31 · $17,400 identified</b><small>Financial measure added</small></div><div><b>09:42 · Correspondence sent</b><small>14 linked documents</small></div></div></div></div>'}
function files(){return '<div class="card"><div class="cardhead"><div><h2>September ULO Report.xlsx</h2><p>3 sheets · 263 rows · $8.4M represented</p></div><div class="row"><button class="btn">Upload workbook</button><button class="btn primary" onclick="importFlow()">Import / map</button></div></div><div class="toolbar"><div class="row"><span class="badge blue">263 detected</span><span class="badge amber">19 possible duplicates</span><span class="badge">47 unclaimed</span></div><button class="btn small" onclick="bulkCorr()">Create correspondence</button></div><div class="tablewrap"><table><thead><tr><th>DOC #</th><th>DODAC</th><th>Amount</th><th>POC</th><th>Status</th><th>Assigned</th><th>Action</th></tr></thead><tbody>'+S.rows.map(function(r){return '<tr><td class="doc">'+r.doc+'</td><td>'+r.dodac+'</td><td>'+money(r.amount)+'</td><td>'+r.poc+'</td><td>'+badge(r.status)+'</td><td>'+r.owner+'</td><td><button class="btn small" onclick="'+(r.owner==='Unclaimed'?'claim('+r.id+')':'complete('+r.id+')')+'">'+(r.owner==='Unclaimed'?'Claim row':'Complete')+'</button></td></tr>'}).join('')+'</tbody></table></div><p>Workbook rows become trackable work. Every claim, status change, amount edit, note, and completion is attributed to the user who made it.</p></div>'}
function corr(){return '<div class="grid2"><div class="card"><div class="cardhead"><h2>Correspondence</h2><button class="btn primary" onclick="draftMail()">+ New thread</button></div><div class="workitem"><div><div class="title">SSgt Smith — Supporting Documentation Request</div><div class="meta"><span class="badge amber">Awaiting response</span><span>14 linked cases</span><span>93 DOC numbers</span></div></div><b>1 day</b></div><div class="workitem"><div><div class="title">GySgt Davis — ULO Status Follow-up</div><div class="meta"><span class="badge green">Response received</span><span>7 linked cases</span></div></div><button class="btn small">Open</button></div></div><div class="card"><h2>One POC · many documents</h2><p>Build one consolidated thread for dozens of DOC numbers. Sending/logging correspondence writes one event to every linked case without duplicating the message.</p><button class="btn soft" onclick="draftMail()">Generate using VANTAGE</button></div></div>'}
function records(){return shell(head('Records','A source-linked professional history built from completed work.','<button class="btn">Export</button>')+'<div class="card"><div class="workitem"><div><div class="title">ULO Reconciliation</div><div class="meta"><span class="badge green">Verified</span><span>14 ULOs reviewed</span><span>$312,842 reviewed</span><span>11 discrepancies resolved</span></div><p>Researched and reconciled assigned ULOs, coordinated with three POCs, and documented corrective actions.</p><small class="muted">Source: September ULO Report.xlsx · 14 linked cases</small></div></div><div class="workitem"><div><div class="title">Financial Management PME</div><div class="meta"><span class="badge">2.5 hours</span><span>Instruction</span></div><p>Developed and delivered structured professional military education supporting peer knowledge.</p></div></div></div>','Records')}
function goals(){var pct=Math.min(100,Math.round(S.goal/1000000*100));return shell(head('Goals','Trackable measures tied to real work rather than manual percentages.','<button class="btn soft" onclick="goalAI()">Generate measures with VANTAGE</button>')+'<div class="card"><div class="cardhead"><div><h2>FY27 ULO Cleanup</h2><p>Target · Sep 30</p></div><span class="badge blue">On track</span></div><div class="goal"><b>Financial value reviewed</b><p>'+money(S.goal)+' / $1,000,000 · '+pct+'%</p><div class="progress"><span style="width:'+pct+'%"></span></div></div><div class="goal"><b>Resolve assigned ULOs</b><p>74 / 90 · 82%</p><div class="progress"><span style="width:82%"></span></div></div><div class="goal"><b>Average case age</b><p>11.2 days / ≤14 days</p><div class="progress"><span style="width:80%"></span></div></div><div class="goal"><b>Cases older than 30 days</b><p>2 / Goal: 0 · Needs attention</p><div class="progress"><span style="width:45%"></span></div></div></div>','Goals')}
function ai(){return shell(head('AI Assist','Advanced workspace using authorized VANTAGE context; AI is also embedded throughout Work, Goals, Records, and Reports.','')+'<div class="chat" id="chat"><div class="msg ai"><b>VANTAGE Assist</b><br>I can reason over authorized cases, actions, workbook work, correspondence, goals, and records. I will not invent authoritative data.</div><div class="msg me">Summarize my open ULO work.</div><div class="msg ai">You have 11 assigned open items. Three are high priority, seven are awaiting response, and two have been open more than seven days. The highest-value unresolved item is M0009180 at $1.205M.</div></div><div class="compose"><input id="aiq" placeholder="Ask about your authorized VANTAGE work"><button class="btn primary" onclick="askAI()">Send</button></div>','AI')}
function owner(){return shell(head('Owner Console','Operational administration plus product telemetry — without treating browser-open time as labor.','<button class="btn">Export analytics</button>')+'<div class="ownergrid"><div class="mini"><span class="muted">DAU</span><strong>38</strong><small>+12%</small></div><div class="mini"><span class="muted">WAU</span><strong>91</strong><small>72% return</small></div><div class="mini"><span class="muted">Actions / user</span><strong>8.4</strong><small>7-day avg</small></div><div class="mini"><span class="muted">Median completion</span><strong>23m</strong><small>Tracked work</small></div></div><div class="grid2" style="margin-top:16px"><div class="card"><h2>Activity creation funnel</h2><div class="bars" style="margin-top:16px"><div class="barrow"><span>Started</span><div class="bar"><span style="width:100%"></span></div><b>247</b></div><div class="barrow"><span>Saved</span><div class="bar"><span style="width:85%"></span></div><b>211</b></div><div class="barrow"><span>Canceled</span><div class="bar"><span style="width:22%"></span></div><b>21</b></div><div class="barrow"><span>Abandoned</span><div class="bar"><span style="width:16%"></span></div><b>15</b></div></div></div><div class="card"><h2>AI operations</h2><p><b>1,482</b> requests · 98.7% success</p><p><b>71%</b> suggestion acceptance</p><p><b>18%</b> edited before acceptance</p><p><b>11%</b> rejected</p></div></div><div class="card" style="margin-top:16px"><h2>Time measurement</h2><p><b>Active VANTAGE time</b> measures foreground interaction. <b>Tracked work time</b> comes from explicit Start / Pause / Complete work sessions. They are stored and reported separately.</p></div>','Owner')}
function modal(){if(!S.modal)return'';var m=S.modal;if(m.type==='case'){var r=m.row;return '<div class="modalbg"><div class="modal"><div class="modalhead"><div><div class="doc">'+r.doc+'</div><h2>ULO / obligation research</h2></div><button class="btn small" onclick="closeM()">×</button></div><div class="modalbody"><div class="ownergrid"><div class="mini"><span class="muted">Amount</span><strong>'+money(r.amount)+'</strong></div><div class="mini"><span class="muted">Status</span><strong style="font-size:16px">'+r.status+'</strong></div><div class="mini"><span class="muted">POC</span><strong style="font-size:16px">'+r.poc+'</strong></div><div class="mini"><span class="muted">Due</span><strong style="font-size:16px">'+r.due+'</strong></div></div><h2 style="margin-top:20px">Timeline</h2><div class="timeline"><div><b>Today 10:03 · Work claimed</b><small>'+r.owner+'</small></div><div><b>Today 10:14 · Reviewed amount '+money(r.amount)+'</b><small>Structured financial measure</small></div><div><b>Today 10:21 · Note added</b><small>Source documentation reviewed.</small></div></div></div><div class="modalfoot"><button class="btn" onclick="draftMail()">Create correspondence</button><button class="btn primary" onclick="complete('+r.id+')">Complete work</button></div></div></div>'}if(m.type==='performance'){return '<div class="modalbg"><div class="modal"><div class="modalhead"><div><h2>Suggested performance action</h2><p>Generated from verified work.</p></div></div><div class="modalbody"><div class="field"><label>Suggested record</label><textarea id="perf" rows="5">Researched and reconciled an ULO valued at '+money(m.amount)+', identifying corrective action and coordinating resolution through targeted correspondence.</textarea></div><p>Measures: 1 case resolved · '+money(m.amount)+' reviewed · source-linked workbook row</p></div><div class="modalfoot"><button class="btn" onclick="closeM()">Don\'t add</button><button class="btn">Edit</button><button class="btn primary" onclick="approve()">Approve</button></div></div></div>'}if(m.type==='mail'){return '<div class="modalbg"><div class="modal"><div class="modalhead"><div><h2>Correspondence draft</h2><p>14 cases · consolidated by POC</p></div><button class="btn small" onclick="closeM()">×</button></div><div class="modalbody"><div class="field"><label>To</label><input value="SSgt Smith"></div><div class="field"><label>Subject</label><input value="Supporting Documentation Request — 14 Open DOCs"></div><div class="field"><label>Message</label><textarea rows="10">Good afternoon SSgt Smith,\n\nI am following up regarding the 14 open document numbers currently associated with the Command Element ULO review. VANTAGE has consolidated the outstanding items below so we can resolve the remaining documentation requirements in one response.\n\nPlease provide the supporting documentation or updated status when available.\n\nRespectfully,\nLCpl Boletz</textarea></div></div><div class="modalfoot"><button class="btn soft">Generate using VANTAGE</button><button class="btn primary" onclick="sent()">Send / log</button></div></div></div>'}if(m.type==='import'){return '<div class="modalbg"><div class="modal"><div class="modalhead"><div><h2>Workbook mapping</h2><p>September ULO Report.xlsx · 263 detected rows</p></div></div><div class="modalbody"><table><tr><th>Workbook column</th><th>VANTAGE field</th></tr><tr><td>DOC NUMBER</td><td>Document ID</td></tr><tr><td>DODAC</td><td>Organization code</td></tr><tr><td>AMOUNT</td><td>Financial value</td></tr><tr><td>POC</td><td>Contact</td></tr><tr><td>STATUS</td><td>Case status</td></tr></table><p>19 probable duplicates detected. Existing cases will be matched rather than duplicated.</p></div><div class="modalfoot"><button class="btn" onclick="closeM()">Cancel</button><button class="btn primary" onclick="finishImport()">Create 244 work items</button></div></div></div>'}return''}
